{
  "component": "Page",
  "props": { "padding": "padding/m", "gap": "padding/m" },
  "children": [
    { "component": "Text", "props": { "text": "Notification Settings", "as": "h1", "style": "m" } },
    {
      "component": "Stack",
      "props": { "gap": "padding/s" },
      "children": [
        {
          "component": "Row",
          "props": { "justify": "between", "align": "center" },
          "children": [
            { "component": "Text", "props": { "text": "Email notifications", "as": "p", "style": "m" } },
            { "component": "Missing", "props": { "need": "switch to turn email notifications on or off", "kind": "component", "closest": "button" } }
          ]
        },
        {
          "component": "Row",
          "props": { "justify": "between", "align": "center" },
          "children": [
            { "component": "Text", "props": { "text": "Push notifications", "as": "p", "style": "m" } },
            { "component": "Missing", "props": { "need": "switch to turn push notifications on or off", "kind": "component", "closest": "button" } }
          ]
        }
      ]
    },
    {
      "component": "Row",
      "props": { "gap": "padding/s", "align": "center" },
      "children": [
        { "component": "button", "props": { "Disabled": "False", "Label": "Save" } },
        { "component": "tag", "props": { "Tone": "Positive", "Label": "Saved", "standInFor": "save confirmation message, shown after Save is pressed" } }
      ]
    }
  ]
}

